import os
import io
import json
import re
from typing import Any, Dict, List, Optional, Tuple

import boto3


def _bytes_from_input(source: Any) -> bytes:
    if source is None:
        raise ValueError("No input provided for OCR.")
    if isinstance(source, bytes):
        return source
    if isinstance(source, str):
        if source.startswith("s3://"):
            match = re.match(r"^s3://([^/]+)/(.+)$", source)
            if not match:
                raise ValueError(f"Invalid S3 URI: {source}")
            bucket, key = match.group(1), match.group(2)
            s3 = boto3.client("s3")
            return s3.get_object(Bucket=bucket, Key=key)["Body"].read()
        if os.path.exists(source):
            with open(source, "rb") as f:
                return f.read()
        return source.encode("utf-8")
    if hasattr(source, "read"):
        data = source.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data
    raise TypeError(f"Unsupported input type: {type(source)}")


def _textract_analyze_bytes(document_bytes: bytes, feature_types: Optional[List[str]] = None) -> Dict[str, Any]:
    textract = boto3.client("textract")
    params = {
        "Document": {"Bytes": document_bytes},
        "FeatureTypes": feature_types or ["FORMS", "TABLES"],
    }
    return textract.analyze_document(**params)


def _build_block_maps(blocks: List[Dict[str, Any]]) -> Tuple[Dict[str, Dict[str, Any]], Dict[str, List[Dict[str, Any]]]]:
    block_by_id = {b["Id"]: b for b in blocks if "Id" in b}
    relationships: Dict[str, List[Dict[str, Any]]] = {}
    for block in blocks:
        for rel in block.get("Relationships", []):
            rel_type = rel.get("Type")
            if rel_type:
                relationships.setdefault(block["Id"], []).append(rel)
    return block_by_id, relationships


def _extract_text_from_block(block_id: str, block_by_id: Dict[str, Dict[str, Any]], visited: Optional[set] = None) -> str:
    if visited is None:
        visited = set()
    if block_id in visited:
        return ""
    visited.add(block_id)

    block = block_by_id.get(block_id, {})
    text = block.get("Text", "")

    for rel in block.get("Relationships", []):
        if rel.get("Type") == "CHILD":
            child_texts = []
            for child_id in rel.get("Ids", []):
                child = block_by_id.get(child_id)
                if not child:
                    continue
                if child.get("BlockType") == "WORD":
                    child_texts.append(child.get("Text", ""))
                elif child.get("BlockType") == "SELECTION_ELEMENT":
                    child_texts.append("[X]" if child.get("SelectionStatus") == "SELECTED" else "[ ]")
                else:
                    extracted = _extract_text_from_block(child_id, block_by_id, visited)
                    if extracted:
                        child_texts.append(extracted)
            if child_texts:
                text = " ".join([t for t in [text] + child_texts if t]).strip()
    return text.strip()


def _extract_forms(blocks: List[Dict[str, Any]]) -> Dict[str, str]:
    block_by_id, _ = _build_block_maps(blocks)
    key_map: Dict[str, str] = {}
    value_map: Dict[str, str] = {}

    for block in blocks:
        if block.get("BlockType") != "KEY_VALUE_SET":
            continue
        entity_types = set(block.get("EntityTypes", []))
        if "KEY" in entity_types:
            key_text = ""
            value_id = None
            for rel in block.get("Relationships", []):
                if rel.get("Type") == "CHILD":
                    key_parts = []
                    for child_id in rel.get("Ids", []):
                        child = block_by_id.get(child_id)
                        if not child:
                            continue
                        if child.get("BlockType") == "WORD":
                            key_parts.append(child.get("Text", ""))
                        elif child.get("BlockType") == "SELECTION_ELEMENT":
                            key_parts.append("[X]" if child.get("SelectionStatus") == "SELECTED" else "[ ]")
                    key_text = " ".join(key_parts).strip()
                elif rel.get("Type") == "VALUE" and rel.get("Ids"):
                    value_id = rel["Ids"][0]
            if key_text and value_id:
                key_map[block["Id"]] = key_text
                value_text = _extract_text_from_block(value_id, block_by_id)
                value_map[block["Id"]] = value_text

    result: Dict[str, str] = {}
    for key_block_id, key_text in key_map.items():
        value_text = value_map.get(key_block_id, "")
        normalized_key = re.sub(r"\s+", " ", key_text).strip().rstrip(":")
        normalized_value = re.sub(r"\s+", " ", value_text).strip()
        if normalized_key:
            result[normalized_key] = normalized_value
    return result


def _extract_lines_and_tables(blocks: List[Dict[str, Any]]) -> Dict[str, Any]:
    block_by_id, _ = _build_block_maps(blocks)
    lines = [b.get("Text", "") for b in blocks if b.get("BlockType") == "LINE" and b.get("Text")]
    tables = []

    for table_block in [b for b in blocks if b.get("BlockType") == "TABLE"]:
        rows: Dict[int, Dict[int, str]] = {}
        for rel in table_block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for cell_id in rel.get("Ids", []):
                cell = block_by_id.get(cell_id, {})
                if cell.get("BlockType") != "CELL":
                    continue
                row_index = int(cell.get("RowIndex", 1))
                col_index = int(cell.get("ColumnIndex", 1))
                cell_text = _extract_text_from_block(cell_id, block_by_id)
                rows.setdefault(row_index, {})[col_index] = cell_text
        max_col = max((max(r.keys()) for r in rows.values()), default=0)
        table_rows = []
        for row_index in sorted(rows):
            row = [rows[row_index].get(col_index, "") for col_index in range(1, max_col + 1)]
            table_rows.append(row)
        if table_rows:
            tables.append(table_rows)

    return {"lines": lines, "tables": tables}


def extract_key_values_from_form(document: Any, feature_types: Optional[List[str]] = None) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Amazon Textract.

    Args:
        document: File path, S3 URI (s3://bucket/key), bytes, or file-like object.
        feature_types: Optional Textract feature types; defaults to ["FORMS", "TABLES"].

    Returns:
        Dictionary with:
            - key_values: extracted form key-value pairs
            - lines: OCR lines
            - tables: extracted tables
            - raw: raw Textract response
    """
    document_bytes = _bytes_from_input(document)
    response = _textract_analyze_bytes(document_bytes, feature_types=feature_types)
    blocks = response.get("Blocks", [])
    key_values = _extract_forms(blocks)
    layout = _extract_lines_and_tables(blocks)

    return {
        "key_values": key_values,
        "lines": layout["lines"],
        "tables": layout["tables"],
        "raw": response,
    }


def extract_key_values_json(document: Any, feature_types: Optional[List[str]] = None) -> str:
    """
    Convenience wrapper returning JSON string.
    """
    result = extract_key_values_from_form(document, feature_types=feature_types)
    return json.dumps(result, ensure_ascii=False, indent=2)
